SELECT import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000005'::uuid, '{"pageId": "e0760000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 76, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "76", "printedPageNumber": 76, "pdfPageNumber": 459, "sequenceIndex": 66, "verificationStatus": "in_review", "scanLanguages": ["en"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": false, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0760100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Story—IV", "sourceIdentifier": null, "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "b0760200-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Story—V", "sourceIdentifier": null, "title": null, "sequenceIndex": 1, "startPageId": null, "endPageId": null}, {"id": "b0760300-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Story—VI", "sourceIdentifier": null, "title": null, "sequenceIndex": 2, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0760000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 76"}, {"id": "f0760100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "who they were. She replied that they were my previous nights and that the ugly one was this night.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 76"}, {"id": "f0760200-0000-4000-8000-000000000001", "structuralNodeId": "b0760100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Story—IV", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 76"}, {"id": "f0760300-0000-4000-8000-000000000001", "structuralNodeId": "b0760100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "An eminent Shaikh says: \"One night I was in a deep sleep and could not get up for Tahajjud. I saw in my dream a girl of such beauty as I had never seen in my life. She was emitting such fragrance as I had never smelt before. She handed over to me a piece of paper on which were written three couplets, which meant, ''You were so enamoured of deep sleep that you have become unmindful of the high balconies of Paradise, where you have to abide for ever with no fear of death. Wake up! It is better to recite the Qur''an in Tahajjud, than to sleep.'' Since then, wherever I feel sleepy, these couplets come to my mind and the sleep goes away.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 76"}, {"id": "f0760400-0000-4000-8000-000000000001", "structuralNodeId": "b0760200-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Story—V", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 76"}, {"id": "f0760500-0000-4000-8000-000000000001", "structuralNodeId": "b0760200-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Ataa (Rahmatullah alaih) writes, \"I went to the market. A person had a slave girl to sell, who was said to be mad; I purchased her for seven dinaars and brought her to my house. After a portion of the night had passed, I noticed that she got up, performed wudhu and started her salaat. In her salaat she wept so much that I thought she would die of excessive crying. After finishing the salaat, she began to supplicate before Allah saying, ''O my Lord! By the love Thou bearest for me, show mercy on me.'' I interrupted by telling her that she should rather say, ''By the love that I have for Thee...!'' She got irritated at this suggestion and said, ''By Allah Himself! Had He not loved me, I would not be standing here before Him while you are in your bed.'' Then she fell prostrate and recited a few couplets purporting, ''I am growing more and more restless. How can one rest whose peace of mind is taken away by love, eagerness and constant anxiety? O, Allah! Show mercy and give some glad tidings.'' Then she prayed in a loud voice thus, ''O Allah! So far the matter between me and Thee has been a secret. Now people have come to know of it. O, Allah! Call me back.'' After saying this, she cried aloud and died on the spot.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 76"}, {"id": "f0760600-0000-4000-8000-000000000001", "structuralNodeId": "b0760300-0000-4000-8000-000000000001", "sequenceIndex": 6, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Story—VI", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 76"}, {"id": "f0760700-0000-4000-8000-000000000001", "structuralNodeId": "b0760300-0000-4000-8000-000000000001", "sequenceIndex": 7, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "A similar thing happened with Sirri (Rahmatullah alaih). He writes: \"I bought a slave woman to attend on me.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 76"}]}'::jsonb);
SELECT import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000005'::uuid, '{"pageId": "e0770000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 77, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "77", "printedPageNumber": 77, "pdfPageNumber": 460, "sequenceIndex": 67, "verificationStatus": "in_review", "scanLanguages": ["en"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": false, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0770100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Story—VII", "sourceIdentifier": null, "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "b0770200-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Story—VIII", "sourceIdentifier": null, "title": null, "sequenceIndex": 1, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0770000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part III (b)—Stories of the Pious", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 77"}, {"id": "f0770100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "She served me for some time, but I was in the dark about her state of affairs. She had a corner in the house reserved for her salaat. After finishing her job, she would go there and offer her salaat. One night, I noticed her performing salaat and then supplicating before Allah. While making her supplication, she said, ''By the love Thou hast for me, do such and such a thing for me.'' I shouted out to her, ''O woman, say by the love that I have for Thee.'' She retorted, ''My Master, if He had not loved me, He would not have made me stand for salaat and deprive you thereof.'' Next morning I sent for her and said to her, ''You are a misfit in your present job. You are exclusively meant for Allah''s service.'' I then gave her some gifts and set her free.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 77"}, {"id": "f0770200-0000-4000-8000-000000000001", "structuralNodeId": "b0770100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Story—VII", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 77"}, {"id": "f0770300-0000-4000-8000-000000000001", "structuralNodeId": "b0770100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Sirri Saqti (Rahmatullah alaih) writes about another woman: \"When she stood up for Tahajjud she would say, ''O Allah! Satan is but Thy creation. Thou hast full power over him. He sees me and I cannot see him. Thou seest him and hast control over all his actions, while he has no control over Thee; O, Allah! repel the evil that he wishes to do me. Requit the wrong he may do to deceive me. I seek Thy refuge from his evil designs and with Thy help I cast him away.'' Thereafter she would cry bitterly. And as a result thereof she lost the sight of one eye. People admonished her to stop excessive weeping, lest she should lose her other eye as well. She replied, \"If it is destined to be an eye of Paradise, Allah will grant me better than this; but if it be that of Hell, then the sooner it is lost the better.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 77"}, {"id": "f0770400-0000-4000-8000-000000000001", "structuralNodeId": "b0770200-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Story—VIII", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 77"}, {"id": "f0770500-0000-4000-8000-000000000001", "structuralNodeId": "b0770200-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Shaikh Abu Abdullah Jilaa says: \"One day my mother asked my father to fetch some fish from the market. My father left for the market and I also accompanied him. The fish was bought and we needed a porter to carry it for us. We engaged a boy who was standing there and who had offered to do the job for us. He put the load on his head and followed us. While we were on our way, we happened to hear the Azaan. The boy abruptly spoke, ''Allah''s summoner has summoned me; I have to take my wudhu too. I shall now carry the fish after salaat. If you like you may wait, otherwise here it is.'' Saying this he put the load down and left for the musjid. My father thought when the", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 77"}]}'::jsonb);
SELECT import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000005'::uuid, '{"pageId": "e0780000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 78, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "78", "printedPageNumber": 78, "pdfPageNumber": 461, "sequenceIndex": 68, "verificationStatus": "in_review", "scanLanguages": ["en"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": false, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0780100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Story—IX", "sourceIdentifier": null, "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "b0780200-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Story—X", "sourceIdentifier": null, "title": null, "sequenceIndex": 1, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0780000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 78"}, {"id": "f0780100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "poor boy could place his trust in Allah so much, we must as well do so in a greater degree. He, therefore, left the fish there and took me to the musjid. When we three returned after saying salaat, we found the fish lying in the same place as we had left it. The boy then carried it to our house. My father related the strange story to my mother who insisted that the boy should be invited to eat some fish with us. When the invitation was extended to him, he said, ''Excuse me I am fasting.'' My father then requested him to have iftaar at our place. To this he said, ''It is not possible for me to return once I am gone. Just possibly, I may stay in a musjid close to your place; if so, then I shall join you in your dinner.'' Saying this he went to the musjid and returned after Maghrib. When the dinner was over, I showed him the room where he could rest in privacy. Now, there lived a crippled woman in our neighbourhood. We were surprised to see her walking quite hale and hearty. When we enquired from her how she got cured, she said, ''I prayed to Allah to heal me for the sake of the blessings that your guest carries. No sooner I prayed than I was healed.'' When we went to find the boy in the room where we had left him, the door was shut and the boy was nowhere to be seen.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 78"}, {"id": "f0780200-0000-4000-8000-000000000001", "structuralNodeId": "b0780100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Story—IX", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 78"}, {"id": "f0780300-0000-4000-8000-000000000001", "structuralNodeId": "b0780100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "It is said of a pious man that once he had a sore on his foot. According to the opinion of the surgeons, if his foot was not amputated, the sore might prove fatal. His mother proposed that the operation should be done while he was absorbed in his salaat. This was done, and no pain was felt by him.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 78"}, {"id": "f0780400-0000-4000-8000-000000000001", "structuralNodeId": "b0780200-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Story—X", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 78"}, {"id": "f0780500-0000-4000-8000-000000000001", "structuralNodeId": "b0780200-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Abu ''Aamir (Rahmatullah alaih) says, \"I saw a slave woman on sale for a very small sum. She was very emaciated and her hair was dirty. I took pity on her and purchased her. I said to her, ''Come, woman, let us go and make purchases for Ramadhaan.'' She remarked, ''Alhamdulillah, all the months are alike for me.'' She fasted on all days and stood in salaat for all nights. When Eid drew near, I said to her, ''Woman! You will go with me tomorrow to make purchases for Eid.'' She remarked, ''My master! You are too much absorbed in this world.'' She then went into", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 78"}]}'::jsonb);
SELECT import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000005'::uuid, '{"pageId": "e0790000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 79, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "79", "printedPageNumber": 79, "pdfPageNumber": 462, "sequenceIndex": 69, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0790100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Story—XI", "sourceIdentifier": null, "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0790000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part III (b)—Stories of the Pious", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 79"}, {"id": "f0790100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "her room and started her salaat. She was reciting Soorah Ibrahim and when she reached the 16th verse of the Soorah (viz.,", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 79"}, {"id": "f0790200-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 2, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "مِنْ وَرَائِهِ جَهَنَّمُ وَيُسْقَىٰ مِنْ مَاءٍ صَدِيدٍ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 79"}, {"id": "f0790300-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 3, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"Hell is before him and he is made to drink boiling fetid water\", which described the doom of a disbeliever, she repeated it again and again, and then gave out a cry and fell dead.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 79"}, {"id": "f0790400-0000-4000-8000-000000000001", "structuralNodeId": "b0790100-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Story—XI", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 79"}, {"id": "f0790500-0000-4000-8000-000000000001", "structuralNodeId": "b0790100-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Everybody knows Umar bin Abdul Aziz (Rahmatullah alaih). After the four Khulafaa-ur Raashideen he is the most eminent Khalifah. His wife says, \"There may be other people more particular about wudhu and salaat; but I have never seen anybody fearing Allah more than my husband. After his daily Ishaa, he would sit at a place reserved for his salaat and raise his hands in supplication and keep crying before Allah till sleep overpowered him. Whenever he woke during the night, he would again start praying and crying before Allah.\"\n\nIt is said that since his becoming Khalifah he never shared the bed with his wife. His wife was the daughter of the great King Abdul Malik. Her father had given her much jewellery in dowry, which included a marvellous diamond. He said to his wife, \"Either part with all your jewellery for the sake of Allah, so that I may deposit it in the Baitul Maal or be separated from me. I would not like to live in a house where there is so much wealth.\" His wife replied, \"I can part with a thousand times more wealth, but I cannot leave you.\" She then deposited everything she had in the Baitul Maal. After the death of Umar bin Abdul Aziz, when Yazeed son of Abdul Malik succeeded him as Khalifa, he said to his sister, \"If you like you may have your jewellery back from the Baitul Maal.\" She replied, \"How can the wealth I discarded during my husband''s lifetime, satisfy me after his death.\"\n\nUmar bin Abdul Aziz was on his death-bed when he inquired from the persons round him about the cause of his disease. Someone said, \"People think it is the effect of black magic.\" He said, \"No, it is not magic.\" He then sent for a particular slave of his and said to him, \"What made you poison me?\" He replied, \"One hundred dinaars and a", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 79"}]}'::jsonb);
SELECT import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000005'::uuid, '{"pageId": "e0800000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 80, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "80", "printedPageNumber": 80, "pdfPageNumber": 463, "sequenceIndex": 70, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0800100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Story—XII", "sourceIdentifier": null, "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "b0800200-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Story—XIII", "sourceIdentifier": null, "title": null, "sequenceIndex": 1, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0800000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 80"}, {"id": "f0800100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "promise of liberty,\" Umar bin Abdul Aziz (Rahmatullah alaih) took those dinaars from the slave and deposited them in the Baitul Maal, and advised him to run away to some distant place where he could not be seized.\n\nJust before his death, Muslimah (Rahmatullah alaih) came to him and said, \"Nobody has ever treated his children as you are doing. None of your thirteen sons has anything to live on.\" He sat up in his bed and said, \"I have not held back from my sons what they were entitled to. I have, of course, refused them what was actually due to others. If my sons are righteous, then Allah will surely be their guardian as He has said in His Book: He is the guardian of the righteous (VII: 196)'', but if they are wrong-doers, then why should I care for them?\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 80"}, {"id": "f0800200-0000-4000-8000-000000000001", "structuralNodeId": "b0800100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Story—XII", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 80"}, {"id": "f0800300-0000-4000-8000-000000000001", "structuralNodeId": "b0800100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Muhammad bin Munkadir (Rahmatullah alaih) was a Hafiz of Hadith. One night, he wept excessively in his Tahajjud. When someone inquired about it, he said, \"During Qiraat, I came across the following words of the Qur''an:", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 80"}, {"id": "f0800400-0000-4000-8000-000000000001", "structuralNodeId": "b0800100-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "وَبَدَا لَهُمْ سَيِّئَاتُ مَا كَسَبُوا وَحَاقَ بِهِمْ مَا كَانُوا بِهِ يَسْتَهْزِئُونَ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 80"}, {"id": "f0800500-0000-4000-8000-000000000001", "structuralNodeId": "b0800100-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"And the evils that they earned will confront them; and they will be surrounded by what they used to scoff at.\" (XXXIX: 48)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 80"}, {"id": "f0800600-0000-4000-8000-000000000001", "structuralNodeId": "b0800100-0000-4000-8000-000000000001", "sequenceIndex": 6, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "He was very anxious and worried at the time of his death, and said that these same words of the Qur''an were looming before him.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 80"}, {"id": "f0800700-0000-4000-8000-000000000001", "structuralNodeId": "b0800200-0000-4000-8000-000000000001", "sequenceIndex": 7, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Story—XIII", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 80"}, {"id": "f0800800-0000-4000-8000-000000000001", "structuralNodeId": "b0800200-0000-4000-8000-000000000001", "sequenceIndex": 8, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Thaabit Banaani (Rahmatullah alaih) is another Hafiz of Hadith. He used to cry a great deal while supplicating before Allah. Someone warned him that he would lose his eyesight if he did not stop weeping like that. He replied to him, \"What use are these eyes if these do not weep before Allah.\"\n\nHe used to ask in his prayer, \"O, Allah! Permit me to offer my salaat in my grave, if ever you grant this privilege to any of Thy slaves!\" Abu Sanaan (Rahmatullah alaih) narrates, \"By Allah! I was among those present at the burial of Thaabit Banaani. Just after he had been placed in his grave, one of the bricks from the side fell off. I peeped into the pit to find to my great amazement, that Thaabit was offering", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 80"}]}'::jsonb);